SourceCode.Declaration:
/// <summary>
/// Scopes processPending and getQueueStatus to one company - everything else about which rows
/// to work is decided server-side (Pending for processing, everything for status).
///
/// IdempotencyKeys (comma separated) narrows getQueueStatus to those postings: how a handheld
/// follows a posting it has handed over until D365FO has a final answer for it.
/// </summary>
[DataContractAttribute]
class HSMobileOpsPostQueueRequest
{
    DataAreaId dataAreaId;
    str        idempotencyKeys;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('IdempotencyKeys')]
public str parmIdempotencyKeys(str _value = idempotencyKeys)
{
    idempotencyKeys = _value;
    return idempotencyKeys;
}
